Write a property test verifying that sorting a list is idempotent and produces a non-decreasing sequence.

def sort_list(items):
    return sorted(items)

output:
from hypothesis import given, strategies as st
from seq import sort_list

@given(st.lists(st.integers()))
def test_sort_idempotent(items):
    once = sort_list(items)
    assert sort_list(once) == once

@given(st.lists(st.integers()))
def test_sort_is_ordered(items):
    result = sort_list(items)
    assert all(result[i] <= result[i + 1] for i in range(len(result) - 1))

