Write a property test stating that filtering never grows a list.

def keep_positive(numbers):
    return [n for n in numbers if n > 0]

output:
from hypothesis import given, strategies as st
from seq import keep_positive

@given(st.lists(st.integers()))
def test_filter_does_not_grow_list(numbers):
    result = keep_positive(numbers)
    assert len(result) <= len(numbers)

@given(st.lists(st.integers()))
def test_filtered_items_all_positive(numbers):
    assert all(n > 0 for n in keep_positive(numbers))

