Write a property test proving clamp always returns a value within [low, high] for any input and valid bounds.

def clamp(value, low, high):
    return max(low, min(value, high))

output:
from hypothesis import given, strategies as st
from mathops import clamp

@given(
    st.integers(),
    st.integers(max_value=0).map(lambda x: x),
    st.integers(min_value=1))
def test_clamp_within_bounds(value, low, high):
    # ensure low <= high by construction: low <= 0 < high
    result = clamp(value, low, high)
    assert low <= result <= high

@given(st.integers(), st.integers(), st.integers())
def test_clamp_idempotent(value, low, high):
    if low > high:
        low, high = high, low
    once = clamp(value, low, high)
    assert clamp(once, low, high) == once

